        /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// To update deliveryshipetoGLN field 
    /// </summary>
    /// <param name="sender">Form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(InventLocation, InventLocation), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventLocation_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        InventLocation      InventLocation = sender.cursor();

        if(InventLocation.METUseDevAddressforShiptoGLNSetting)
        {
            sender.object(fieldNum(InventLocation, METPODeliveryShiptoGLN)).enabled(NoYes::No);
            InventLocation.METPODeliveryShiptoGLN = METConstants::emptyString;
        }
        else
        {
            sender.object(fieldNum(InventLocation, METPODeliveryShiptoGLN)).enabled(NoYes::Yes);
        }
    }

    /// <summary>
    /// Method to write to METInventLocation on write of the InventLocation table
    /// </summary>
    /// <param name="sender">formdatasource</param>
    /// <param name="e">arguments</param>
    [FormDataSourceEventHandler(formDataSourceStr(InventLocation, InventLocation), FormDataSourceEventType::Written),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventLocation_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun                     element = sender.formRun();
        FormDataSource              metInventLocation_ds;
        METInventLocation           metInventLocation;
        InventLocation              inventLocation;

        metInventLocation_ds = element.dataSource(formDataSourceStr(InventLocation, METInventLocation));

        if (metInventLocation_ds)
        {
            inventLocation      = sender.cursor();
            metInventLocation   = metInventLocation_ds.cursor();
            inventLocation.metPackmetInventLocation(metInventLocation);
            metInventLocation.SysExtensionSerializerExtensionMap::insertAfterBaseTable(inventLocation);
        }
    }

    /// <summary>
    /// CB715_TransferOrderExtract
    /// </summary>
    /// <param name="sender">
    /// The Pillar form control
    /// </param>
    /// <param name="e">
    /// Form control event parameter
    /// </param>
    [FormControlEventHandler(formControlStr(InventLocation, METInventLocation_Pillar), FormControlEventType::Lookup),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METInventLocation_Pillar_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        #define.DimensionName('Pillar')
        Query                   query = new Query();
        QueryBuildDataSource    qbds,qbds1;
        SysTableLookup          sysTableLookup;        
        DimensionAttribute      dimAttr;

        sysTableLookup  = sysTableLookup::newParameters(tableNum(DimensionFinancialTag), sender);
        dimAttr         = DimensionAttribute::findByName(#DimensionName); //Financial Dimension Name
        sysTableLookup.addLookupField(fieldnum(DimensionFinancialTag, Value));
        sysTableLookup.addLookupField(fieldnum(DimensionFinancialTag, Description));

        qbds = query.addDataSource(tableNum(DimensionFinancialTag));
        qbds1 = qbds.addDataSource(tableNum(DimensionAttributeDirCategory));
        qbds1.addLink(fieldNum(DimensionFinancialTag,FinancialTagCategory),fieldnum(DimensionAttributeDirCategory,RecId));
        qbds1.addRange(fieldNum(DimensionAttributeDirCategory, DimensionAttribute)).value(queryvalue(dimAttr.recid));

        sysTableLookup.parmQuery(query);
        sysTableLookup.parmUseLookupValue(false);
        sysTableLookup.performFormLookup();
    }
